const splitAddress = (addr: string) => {
  if (!addr) return { main: "Detecting Location...", sub: "Current Area" };
  const parts = addr.split(",").map(p => p.trim()).filter(Boolean);
  if (parts.length === 0) return { main: "VR Colony", sub: "Hyderabad" };
  
  const main = parts[0];
  const remainingParts = parts.slice(1);
  
  // Filter out redundant/unnecessary details for a minimized, elegant header
  const cleanedSubParts = remainingParts.filter(part => {
    const lower = part.toLowerCase();
    if (lower === "india" || lower === "united states" || lower === "usa") return false;
    if (lower === "telangana" || lower === "andhra pradesh" || lower === "maharashtra") return false;
    if (/^\d{5,6}$/.test(part)) return false; // exclude postal codes
    return true;
  });
  
  const sourceParts = cleanedSubParts.length > 0 ? cleanedSubParts : remainingParts;
  // Take up to 2 segments maximum for a clean, concise sub-address
  const sub = sourceParts.slice(0, 2).join(", ");
  
  return {
    main: main || "VR Colony",
    sub: sub || "Hyderabad",
  };
};

const isValidLatLng = (latlng: any): boolean => {
  if (!latlng) return false;
  try {
    if (Array.isArray(latlng)) {
      const lat = Number(latlng[0]);
      const lng = Number(latlng[1]);
      return !isNaN(lat) && !isNaN(lng) && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180;
    }
    const lat = Number(latlng.lat != null ? latlng.lat : latlng[0]);
    const lng = Number(latlng.lng != null ? latlng.lng : (latlng.lon != null ? latlng.lon : latlng[1]));
    return !isNaN(lat) && !isNaN(lng) && lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180;
  } catch (e) {
    return false;
  }
};

const isGenericAddress = (addr: any): boolean => {
  if (!addr || typeof addr !== "string") return true;
  const s = addr.trim().toLowerCase();
  return (
    s === "" ||
    s === "pickup address" ||
    s === "drop-off address" ||
    s === "dropoff address" ||
    s === "pickup location" ||
    s === "dropoff location" ||
    s === "destination" ||
    s === "pickup" ||
    s === "drop" ||
    s === "drop-off"
  );
};

const getResolvedPickupAddress = (trip: any, allTrips: any[] = []): string => {
  if (!trip) return "Bompally, Peddapalli";
  const candidates = [
    trip.from,
    trip.pickup?.address,
    typeof trip.pickup === "string" ? trip.pickup : null,
    trip.pickupAddress,
    trip.fromAddress,
    trip.boardingHub,
    trip.origin,
    trip.pickupLocation,
    trip.sourcePost?.from,
    trip.sourcePost?.pickup?.address,
  ];

  for (const c of candidates) {
    if (c && !isGenericAddress(c)) return c;
  }

  if (trip.postId) {
    const post = allTrips.find((p: any) => p.id === trip.postId);
    if (post) {
      const postCandidates = [
        post.from,
        post.pickup?.address,
        typeof post.pickup === "string" ? post.pickup : null,
        post.pickupAddress,
        post.fromAddress,
        post.boardingHub,
        post.origin,
      ];
      for (const pc of postCandidates) {
        if (pc && !isGenericAddress(pc)) return pc;
      }
    }
  }

  return "Bompally, Peddapalli";
};

const getResolvedDropAddress = (trip: any, allTrips: any[] = []): string => {
  if (!trip) return "Gollapally, Peddapalli";
  const candidates = [
    trip.to,
    trip.drop?.address,
    typeof trip.drop === "string" ? trip.drop : null,
    trip.dropAddress,
    trip.toAddress,
    trip.destinationHub,
    trip.destination,
    trip.dropLocation,
    trip.sourcePost?.to,
    trip.sourcePost?.drop?.address,
  ];

  for (const c of candidates) {
    if (c && !isGenericAddress(c)) return c;
  }

  if (trip.postId) {
    const post = allTrips.find((p: any) => p.id === trip.postId);
    if (post) {
      const postCandidates = [
        post.to,
        post.drop?.address,
        typeof post.drop === "string" ? post.drop : null,
        post.dropAddress,
        post.toAddress,
        post.destinationHub,
        post.destination,
      ];
      for (const pc of postCandidates) {
        if (pc && !isGenericAddress(pc)) return pc;
      }
    }
  }

  return "Gollapally, Peddapalli";
};

const getScheduledStatusBadge = (status: string) => {
  if (!status) return null;
  const s = status.toLowerCase();
  if (s === "accepted") return null;
  if (s === "completed" || s === "arrived") {
    return (
      <div className="flex items-center gap-1.5 px-3 py-1 rounded-xl border border-green-150 bg-green-50 text-green-600 shadow-sm shrink-0">
        <span className="text-[10px] font-black uppercase tracking-wider">
          COMPLETED
        </span>
      </div>
    );
  }
  return (
    <div className="flex items-center gap-1.5 px-3 py-1 rounded-xl border border-slate-200 bg-slate-50 text-slate-500 shadow-sm shrink-0">
      <span className="text-[9px] font-black uppercase tracking-wider">
        {status.toUpperCase()}
      </span>
    </div>
  );
};

