const BoundsHandler = ({ path }: { path: [number, number][] }) => {
  const map = useMap();
  useEffect(() => {
    if (path && path.length > 1) {
      const validPath = path.filter(
        (p) => p && p.length >= 2 && !isNaN(p[0]) && !isNaN(p[1]),
      );
      if (validPath.length > 1) {
        try {
          const bounds = L.latLngBounds(validPath);
          // Adjusted padding to keep the route in the upper 60% of the screen
          // so it appears "above" the estimate details card
          map.fitBounds(bounds, {
            paddingTopLeft: [40, 60],
            paddingBottomRight: [40, 280],
            animate: true,
            maxZoom: 15,
          });
        } catch (e) {
          console.error("BoundsHandler failed to fit bounds: ", e);
        }
      }
    }
  }, [path, map]);
  return null;
};

const MapViewHandler = ({ center }: { center: [number, number] }) => {
  const map = useMap();
  useEffect(() => {
    if (center && !isNaN(center[0]) && !isNaN(center[1])) {
      try {
        map.setView(center, map.getZoom(), { animate: true });
      } catch (e) {
        console.error("MapViewHandler failed to set view: ", e);
      }
    }
  }, [center, map]);
  return null;
};

