const getCityFromAddress = (address: string): string => {
  if (!address) return "";
  const clean = address.toLowerCase();
  if (clean.includes("pune")) return "pune";
  if (clean.includes("mumbai")) return "mumbai";
  if (clean.includes("hyderabad")) return "hyderabad";
  if (clean.includes("secunderabad")) return "secunderabad";
  if (clean.includes("peddapalli")) return "peddapalli";
  if (clean.includes("mancherial")) return "mancherial";
  if (clean.includes("ramagundam")) return "ramagundam";
  if (clean.includes("karimnagar")) return "karimnagar";
  if (clean.includes("warangal") || clean.includes("hanmakonda") || clean.includes("kazipet")) return "warangal";
  if (clean.includes("kagaznagar")) return "kagaznagar";
  if (clean.includes("bellampalli")) return "bellampalli";
  if (clean.includes("sultanabad")) return "sultanabad";
  if (clean.includes("godavarikhani")) return "godavarikhani";
  if (clean.includes("bangalore") || clean.includes("bengaluru"))
    return "bangalore";
  if (clean.includes("delhi")) return "delhi";
  if (clean.includes("chennai")) return "chennai";
  if (clean.includes("kolkata")) return "kolkata";

  const parts = address.split(",");
  if (parts.length > 1) {
    let segment = parts[parts.length - 1].trim().toLowerCase();
    if (segment === "india" && parts.length > 2) {
      segment = parts[parts.length - 2].trim().toLowerCase();
    }
    if ((segment === "telangana" || segment === "maharashtra" || segment === "karnataka" || segment === "tamil nadu" || segment === "west bengal" || segment === "andhra pradesh") && parts.length > 2) {
      const offset = parts[parts.length - 1].trim().toLowerCase() === "india" ? 3 : 2;
      if (parts.length > offset) {
        segment = parts[parts.length - offset].trim().toLowerCase();
      }
    }
    return segment;
  }
  return address.trim().toLowerCase();
};

const LiveVehiclePanTracker = ({
  vehiclePos,
  isAutoTracking,
  onUserInteract,
}: {
  vehiclePos: [number, number] | null;
  isAutoTracking: boolean;
  onUserInteract: () => void;
}) => {
  const map = useMap();

  useMapEvents({
    dragstart: () => onUserInteract(),
    zoomstart: () => onUserInteract(),
    movestart: () => onUserInteract(),
  });

  useEffect(() => {
    if (!isAutoTracking || !vehiclePos || isNaN(vehiclePos[0]) || isNaN(vehiclePos[1])) return;

    try {
      map.panTo(vehiclePos, {
        animate: true,
        duration: 0.35,
        easeLinearity: 0.25,
      });
    } catch (e) {
      console.error("Auto pan error:", e);
    }
  }, [vehiclePos, isAutoTracking, map]);

  return null;
};

