              lastMsg.senderId === "DRV26HYM57P8Z1K" ||
              lastMsg.senderId?.toLowerCase().includes("driver") ||
              lastMsg.senderName?.toLowerCase().includes("driver") ||
              lastMsg.senderName?.toLowerCase().includes("kabir")
