  const [otpStatus, setOtpStatus] = useState<"idle" | "wrong" | "right">(
    "idle",
  );

  const handleVerifyOtp = async (val: string) => {
    const targetTrip =
      activeTrip ||
      (incomingRequest
        ? {
            id: incomingRequest.id,
            otp: incomingRequest.otp || incomingRequest.fullData?.otp || "1234",
            pickupCoords: incomingRequest.pickupCoords,
            dropCoords: incomingRequest.dropCoords,
            pickup: {
              lat: incomingRequest.pickupCoords?.[0],
              lng: incomingRequest.pickupCoords?.[1],
            },
            drop: {
              lat: incomingRequest.dropCoords?.[0],
              lng: incomingRequest.dropCoords?.[1],
            },
          }
        : null);

    if (!targetTrip) return;
    if (val.length === 4) {
      const tripOtp = targetTrip.otp || "1234";
      if (String(val) === String(tripOtp)) {
        setOtpStatus("right");
        try {
          const res = await fetch(`/api/trips/${targetTrip.id}/verify-otp`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ otp: val }),
          });
          if (res.ok) {
            setTimeout(() => {
              setCurrentCheckpoint("STARTED");
              setAllTrips((prev) =>
                prev.map((t) =>
                  t.id === targetTrip.id
                    ? { ...t, subStatus: "started", status: "started" }
                    : t,
                ),
              );

              // Generate path for trip simulation (pickup -> destination)
              const startLat =
                targetTrip.pickupCoords?.[0] ||
                targetTrip.pickup?.lat ||
                17.385;
              const startLng =
                targetTrip.pickupCoords?.[1] ||
                targetTrip.pickup?.lng ||
                78.4867;
              const endLat =
                targetTrip.dropCoords?.[0] || targetTrip.drop?.lat || 17.4948;
              const endLng =
                targetTrip.dropCoords?.[1] || targetTrip.drop?.lng || 78.3996;
              const startPos = [startLat, startLng];
              const endPos = [endLat, endLng];
              const simulationPath = [];
              for (let i = 0; i <= 30; i++) {
                simulationPath.push([
                  startPos[0] + (endPos[0] - startPos[0]) * (i / 30),
                  startPos[1] + (endPos[1] - startPos[1]) * (i / 30),
                ]);
              }
              setTripPath(simulationPath);
              setIsArriving(true);
              setOtpStatus("idle");
              setEnteredOtp("");
              setIsDriverOtpModalOpen(false);
              addNotification("Trip Started Successfully!", "success");
            }, 800);
          }
        } catch (e) {
          console.error("OTP verification failed", e);
          setOtpStatus("wrong");
        }
      } else {
        setOtpStatus("wrong");
        setTimeout(() => {
          setOtpStatus("idle");
          setEnteredOtp("");
        }, 1500);
      }
    }
  };
