  // Debounced geocoding search for editing an existing address
  useEffect(() => {
    const query = editPlaceAddress.trim();
    if (query.length < 3) {
      setEditPlacesSuggestions([]);
      return;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(async () => {
      setIsSearchingEditPlaces(true);
      try {
        const response = await fetch(
          `/api/geocode/search?format=json&q=${encodeURIComponent(query)}&limit=5`,
          { signal: controller.signal }
        );
        if (response.ok) {
          const data = await response.json();
          setEditPlacesSuggestions(data || []);
        }
      } catch (err: any) {
        if (err.name !== "AbortError") {
          console.error("Error fetching edit places suggestions:", err);
        }
      } finally {
        setIsSearchingEditPlaces(false);
      }
    }, 400);

    return () => {
      clearTimeout(timeoutId);
      controller.abort();
    };
  }, [editPlaceAddress]);

