  const handleSendOtp = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    setLoginError("");
    if (!loginPhone || loginPhone.trim().length < 8) {
      setLoginError("Enter a valid phone number (e.g. +919876543210)");
      return;
    }

    // Automatically convert standard 10-digit Indian numbers to E.164 format
    let formattedPhone = loginPhone.trim();
    if (/^\d{10}$/.test(formattedPhone)) {
      formattedPhone = `+91${formattedPhone}`;
      setLoginPhone(formattedPhone);
    } else if (!formattedPhone.startsWith("+")) {
      const numericPart = formattedPhone.replace(/\D/g, "");
      if (numericPart.length === 10) {
        formattedPhone = `+91${numericPart}`;
        setLoginPhone(formattedPhone);
      } else {
        formattedPhone = `+${numericPart}`;
        setLoginPhone(formattedPhone);
      }
    }

    let isFirebaseSent = false;
    try {
      await sendFirebasePhoneOtp(formattedPhone, "recaptcha-container");
      isFirebaseSent = true;
      setOtpSent(true);
      setLoginTimer(60);
      addNotification(
        `📲 Real SMS verification code sent to ${formattedPhone} via Firebase!`,
        "success",
      );
    } catch (fbErr: any) {
      console.warn("[FIREBASE AUTH NOTICE] Using server OTP fallback:", fbErr.message || fbErr);
    }

    try {
      // Standard Platform SMS / Simulation fallback
      const sResponse = await fetch("/api/auth/request-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone: formattedPhone }),
      });
      if (sResponse.ok) {
        const sData = await sResponse.json();
        setSimulatedOtpCode(sData.otp);
        setOtpSent(true);
        setLoginTimer(60);
        if (!isFirebaseSent) {
          addNotification(
            `📲 SMS OTP sent to ${formattedPhone}. Please check your phone messages.`,
            "success",
          );
        }
      } else if (!isFirebaseSent) {
        const errData = await sResponse.json();
        setLoginError(errData.error || "Failed to request SMS OTP.");
      }
    } catch (err) {
      if (!isFirebaseSent) {
        setLoginError("Could not contact OTP server.");
      }
    }
  };

  const handleVerifyLoginOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError("");
    if (!loginOtp || loginOtp.length < 4) {
      setLoginError("Enter a valid OTP passcode.");
      return;
    }

    let verifiedWithFirebase = false;
    try {
      const fbRes = await verifyFirebasePhoneOtp(loginOtp);
      if (fbRes && fbRes.user) {
        verifiedWithFirebase = true;
      }
    } catch (fbVerifyErr) {
      console.log("[FIREBASE VERIFY CHECK] Checking backend verify...", fbVerifyErr);
    }

    try {
      // Sync verified profile to the central backend database
      const response = await fetch("/api/auth/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          phone: loginPhone,
          otp: loginOtp,
          role: verificationRole,
        }),
      });

      if (response.ok || verifiedWithFirebase) {
        const syncedUser = response.ok ? await response.json() : {
          id: `USR_${loginPhone.replace(/\D/g, "").slice(-8)}`,
          name: `User ${loginPhone.slice(-4)}`,
          phone: loginPhone,
          role: verificationRole,
          status: verificationRole === "driver" ? "Pending" : "Active"
        };
        setUserProfile(syncedUser);
        setUserId(syncedUser.id);
        localStorage.setItem("ride-buddy-user-id", syncedUser.id);
        setIsLoggedIn(true);
        setAppMode(syncedUser.role === "rider" ? "rider" : "driver");

        // If driver logging in, enforce document verification
        if (syncedUser.role === "driver") {
          if (syncedUser.status === "Pending") {
            setIsDriverVerified(false);
            setVerificationStep("documents");
            setOnboardingStep(1);
            setShowVerificationModal(true);
          } else {
            setIsDriverVerified(true);
            setVerificationStep("verified");
          }
        }

        if (syncedUser.role !== "rider") {
          setTimeout(() => setShowPwaPopup(true), 1500);
        }
        addNotification(`Welcome back, ${syncedUser.name}!`, "success");

        requestLocationPermission();
        requestNotificationPermission();
      } else {
        const errData = await response.json();
        setLoginError(errData.error || "Invalid OTP code. Please check and try again.");
      }
    } catch (err) {
      setLoginError("Verification service connection error.");
    }
  };

