  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError("");
    try {
      const res = await fetch("/api/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: loginEmail, password: loginPassword, role: verificationRole }),
      });
      if (res.ok) {
        const data = await res.json();
        setUserProfile(data);
        setUserId(data.id);
        localStorage.setItem("ride-buddy-user-id", data.id);
        setIsLoggedIn(true);
        // data.role is 'rider' or 'driver'
        setAppMode(data.role === "rider" ? "rider" : "driver");

        // Refinement 5: Show PWA Onboarding Popup After Login (Driver only)
        if (data.role !== "rider") {
          setTimeout(() => setShowPwaPopup(true), 1500);
        }

        if (data.role === "driver") {
          // If driver hasn't completed onboarding, set onboarding step
          // For demo, if they have a name, assume they are at least at step 6/7
          if (!data.name || data.name === "New Driver") {
            setOnboardingStep(1);
          } else {
            setOnboardingStep(data.role === "driver" && !data.convertedFromRider ? 7 : 5);
          }
        }

        addNotification(`Welcome back, ${data.name}!`, "success");

        // Request permissions immediately after login
        requestLocationPermission();
        requestNotificationPermission();
      } else {
        const data = await res.json();
        setLoginError(data.error || "Invalid credentials.");
      }
    } catch (err) {
      setLoginError("Server error. Please try again.");
    }
  };

  const handleSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError("");
    const reqs = config.loginSettings?.requiredFields || { name: true, email: true, phone: true, vehicle: true };
    if (
      (reqs.name !== false && !signUpName) ||
      (reqs.email !== false && !signUpEmail) ||
      (reqs.phone !== false && !signUpPhone) ||
      !signUpPassword ||
      (verificationRole === "driver" && reqs.vehicle !== false && !signUpVehicle)
    ) {
      setLoginError("Please fill out all required fields.");
      return;
    }
    const randSuffix = Math.floor(1000 + Math.random() * 9000);
    const finalEmail = signUpEmail || `user_${randSuffix}@taxiapp.com`;
    const finalPhone = signUpPhone || `+9199999${randSuffix}`;
    const finalName = signUpName || `User ${randSuffix}`;
    const finalVehicle = verificationRole === "driver" ? (signUpVehicle || "Swift (MH12 AA 1111)") : undefined;

    try {
      const res = await fetch("/api/auth/signup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: finalName,
          email: finalEmail,
          password: signUpPassword,
          phone: finalPhone,
          role: verificationRole,
          vehicle: finalVehicle,
        }),
      });
      const data = await res.json();
      if (res.ok) {
        setUserProfile(data);
        setUserId(data.id);
        localStorage.setItem("ride-buddy-user-id", data.id);
        setIsLoggedIn(true);
        setAppMode(data.role === "rider" ? "rider" : "driver");

        if (!localStorage.getItem(`walkthrough_seen_${data.id}`)) {
          setShowOnboardingWalkthrough(true);
        }

        if (data.role !== "rider") {
          setTimeout(() => setShowPwaPopup(true), 1500);
        }

        if (data.role === "driver") {
          setOnboardingStep(7);
        }

        addNotification(`Welcome, ${data.name}! Your account has been created.`, "success");
        requestLocationPermission();
        requestNotificationPermission();

        // Clear signup form
        setSignUpName("");
        setSignUpEmail("");
        setSignUpPassword("");
        setSignUpPhone("");
        setSignUpVehicle("");
        setIsSignUp(false);
      } else {
        setLoginError(data.error || "Failed to sign up.");
      }
    } catch (err: any) {
      console.error(err);
      setLoginError("Failed to connect to authentication server.");
    }
  };

