  const handleRejectBooking = async (reason: string) => {
    if (!bookingToReject) return;
    try {
      const finalReason = reason === "Other" && customRejectReason.trim() ? customRejectReason.trim() : reason;
      await fetch(`/api/trips/${bookingToReject.id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          status: "rejected",
          rejectReason: finalReason,
        }),
      });
      setAllTrips((prev: any[]) =>
        prev.map((t) =>
          t.id === bookingToReject.id
            ? { ...t, status: "rejected", rejectReason: finalReason }
            : t
        )
      );
      if (appMode === "rider") {
        addNotification("Driver offer rejected and ride request reopened for nearby drivers.", "success");
      } else {
        addNotification("Rider removed and booking request cancelled.", "success");
      }
      setShowRejectModal(false);
      setBookingToReject(null);
      setSelectedRejectReason("");
      setCustomRejectReason("");
    } catch (err) {
      addNotification("Failed to process rejection.", "info");
    }
  };

