  const handleExternalNav = (
    platform: "google" | "apple",
    customPickup?: [number, number],
    customDrop?: [number, number],
    waypoints?: [number, number][],
  ) => {
    const pCoords = customPickup || pickupCoords;
    const dCoords = customDrop || dropCoords;

    if (!pCoords || !dCoords) {
      addNotification?.("GPS coordinates not available for navigation", "info");
      return;
    }

    const origin = `${pCoords[0]},${pCoords[1]}`;
    const destination = `${dCoords[0]},${dCoords[1]}`;

    let url = "";
    if (platform === "google") {
      const waypointStr =
        waypoints && waypoints.length > 0
          ? `&waypoints=${waypoints.map((w) => `${w[0]},${w[1]}`).join("|")}`
          : "";
      url = `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}${waypointStr}&travelmode=driving`;
    } else {
      // Apple Maps doesn't support waypoints in a simple URL as effectively as Google,
      // but we can set destination and multiple address params if they were addresses.
      // For coordinates, we usually just go to the destination or use daddr with multiple points if using old syntax.
      // Standard approach for multi-point in Apple Maps is limited via URL, so we prioritize Google for full routes.
      url = `https://maps.apple.com/?saddr=${origin}&daddr=${destination}&dirflg=d`;
    }
    window.open(url, "_blank");
  };

