  const [showActiveTripConflictModal, setShowActiveTripConflictModal] = useState(false);
  const [activeTripConflictTargetMode, setActiveTripConflictTargetMode] = useState<AppMode>("driver");

  const handleModeSwitch = (newMode: AppMode) => {
    // 1. Simultaneous Active Trips (State Conflict Prevention with Action Control)
    if (hasAnyActiveTrip) {
      setActiveTripConflictTargetMode(newMode);
      setShowActiveTripConflictModal(true);
      return;
    }

    // 2. Allow mode switch smoothly while keeping user logged in; if driver profile is pending verification, open driver onboarding/verification modal without logging out
    if (newMode === "driver") {
      const isApprovedDriver =
        userProfile?.role === "driver" &&
        userProfile?.driver_kyc_status === "Approved" &&
        isDriverVerified;

      if (!isApprovedDriver && userProfile?.role !== "driver") {
        // Upgrade current logged-in profile to driver mode and guide through verification
        setUserProfile((prev: any) => {
          const updated = {
            ...prev,
            role: "driver",
            driver_kyc_status: prev?.driver_kyc_status || "Pending",
          };
          try {
            localStorage.setItem("ride-buddy-user-profile", JSON.stringify(updated));
          } catch (e) {}
          return updated;
        });
        setOnboardingStep(1);
        setShowVerificationModal(true);
      }
    }

    setAppMode(newMode);

    // Reset core states
    setStep("idle");
    setBookingStatus("idle");
    setPickup("Banjara Hills, Hyderabad");
    setDrop("");
    setDropCoords(null);
    setSelectedOption(null);
    setIsSearchMinimized(false);

    // Navigation cleanup
    setCurrentTab("home");

    if (newMode === "driver") {
      setTripsTab("Live");
      if (!isDriverOnline) {
        setShowOnlineOverlay(true);
      }
    } else {
      setTripsTab("Live");
      setIsDriverOnline(false);
      setTripsFilterIdx(0); // Default to Discover Offers (0) for rider
    }
  };

