    const maintTagline = maint.tagline || 'System Infrastructure & Security Optimization';
    const maintMessage = maint.message || 'We are currently upgrading our core server infrastructure, database security pipelines, and dispatch systems to serve you better. All live bookings are temporarily paused.';
