              exit="exit"
              className="flex-1 px-3 sm:px-6 overflow-y-auto transition-colors duration-300 pt-3 sm:pt-6 pb-32 sm:pb-40 bg-slate-50 dark:bg-[#12161f]"
            >
              <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-2xl mx-auto flex flex-col"
              >
                <VerificationModal
                  isOpen={true}
                  onClose={() => setCurrentTab("profile")}
                  step={verificationStep}
                  docs={verificationDocs}
                  status={userProfile?.status}
                  rejectionReason={userProfile?.rejectionReason}
                  userProfile={userProfile}
                  isInline={true}
                  onUpload={(type, url) => {
                    if (type === "start") setVerificationStep("documents");
                    else {
                      setVerificationDocs((prev) => ({
                        ...prev,
                        [type]: true,
                        [`${type}Url`]: url || "",
                      }));
                    }
                  }}
                  onSubmit={async (details) => {
                    setVerificationStep("pending");
                    const targetDriverId = userId || userProfile?.id;
                    if (!targetDriverId) return;

                    const payload = {
                      driverId: targetDriverId,
                      name: details?.fullName || userProfile?.name,
                      workCity: details?.workCity || userProfile?.city || "Pune",
                      plate: details?.vehicleNumber || userProfile?.plate || "MH12 AB 1234",
                      vehicle: details?.vehicleNumber
                        ? `${details.vehicleType || "Sedan"} (${details.vehicleNumber})`
                        : details?.vehicleType || userProfile?.vehicle || "White Swift",
                      licenseUrl: verificationDocs.licenseUrl || "https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=400&q=80",
                      rcUrl: verificationDocs.rcUrl || "https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=400&q=80",
                      selfieUrl: verificationDocs.selfieUrl || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80",
                      vehiclePhotoUrl: verificationDocs.vehiclePhotoUrl || "https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=400&q=80",
                      aadhaarUrl: verificationDocs.aadhaarUrl || "https://images.unsplash.com/photo-1541534741688-6078c6bfb5c5?auto=format&fit=crop&w=400&q=80",
                      status: "Active",
                      isVerified: true,
                      driver_kyc_status: "Approved",
                      role: "driver"
                    };

                    try {
                      await fetch("/api/auth/driver/update", {
                        method: "POST",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify(payload)
                      });
                      try {
                        const socket = io();
                        socket.emit("driver_kyc_submitted", payload);
                        socket.emit("driver_update", payload);
                      } catch (err) {}
                    } catch (e) {
                      console.error("Error updating driver verification:", e);
                    }

                    const updatedProfile = {
                      ...userProfile,
                      ...payload,
                      status: "Active",
                      isVerified: true,
                      driver_kyc_status: "Approved",
                      role: "driver"
                    };
                    setUserProfile(updatedProfile);
                    setIsDriverVerified(true);
                    setAppMode("driver");
                    setCurrentTab("home");
                    addNotification?.(
                      "Driver registration complete! Welcome to Driver mode.",
                      "success"
                    );
                  }}
                  onboardingStep={onboardingStep}
                  setOnboardingStep={setOnboardingStep}
                />
              </motion.div>
